1	// src/lib/plattform/backend/demo.js
2	//
3	// Demo-Backend: vollständige Referenz-Implementierung der Plattform-Schnittstelle
4	// (siehe backend/index.js und docs/API.md) auf einer lokalen JSON-Datei.
5	// Rechte (Rolle UND Eigentum) und Zustandsautomaten (prozesse.js) werden HIER
6	// erzwungen – die API-Routen prüfen zusätzlich vorab Anmeldung und Rolle.
7	
8	import { PROVISION } from "@/lib/invest/markt";
9	import {
10	  BEZUG_ARTEN, DOKUMENT_KATEGORIEN, FLAECHE_NUTZUNG, LAENDER, NDA, NETZANSCHLUSS, PREIS_MODUS, PROJEKT_TYPEN,
11	  ROLLE_FUER_TYP, ROLLEN_IDS, UPLOAD, VORGANG_TYPEN, BUNDESLAENDER,
12	} from "../konstanten";
13	import { BOERSE_STATUS, DATENRAUM_STATUS, OFFENE_STATUS, PROZESSE, pruefeUebergang, statusLabel } from "../prozesse";
14	import { PlattformFehler, konflikt, nichtGefunden, ungueltig, verboten } from "../fehler";
15	import * as v from "../validierung";
16	import { projektOeffentlich, projektVertraulich } from "../oeffentlich";
17	import { matching } from "../matching";
18	import { PHASEN } from "@/lib/invest/markt";
19	import { passwortHash, passwortPruefen } from "../server/passwort";
20	import { aendern, lesen, seedSetzen, uploadLesen, uploadLoeschen, uploadSchreiben } from "./demo/speicher";
21	import { seedErstellen } from "./demo/seed";
22	import { jetzt, neueId, sha256, slugify, zufallsToken } from "./demo/hilfen";
23	
24	seedSetzen(seedErstellen);
25	
26	export const name = "demo";
27	
28	// ================================================================ Helfer
29	
30	const SAMMLUNG = { vorgang: "vorgaenge", flaeche: "flaechen", projekt: "projekte", interesse: "interessen", provision: "provisionen" };
31	
32	const istAdmin = (n) => !!n?.rollen?.includes("admin");
33	const hatRolle = (n, rollen) => istAdmin(n) || rollen.some((r) => n?.rollen?.includes(r));
34	
35	function rolleNoetig(n, rollen, text) {
36	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
37	  if (!hatRolle(n, rollen)) throw verboten(text);
38	}
39	function adminNoetig(n) {
40	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
41	  if (!istAdmin(n)) throw verboten("Nur für das Backoffice.");
42	}
43	
44	function ohneGeheimnis(u) {
45	  if (!u) return null;
46	  const { passwortHash: _p, ...rest } = u;
47	  return rest;
48	}
49	const kurz = (u) => (u ? { id: u.id, vorname: u.vorname, nachname: u.nachname, email: u.email, firma: u.firma || "" } : null);
50	const nutzerById = (db, id) => db.nutzer.find((u) => u.id === id) || null;
51	
52	function objekt(db, art, id) {
53	  const liste = db[SAMMLUNG[art]];
54	  if (!liste) throw ungueltig("Unbekannte Objektart");
55	  return liste.find((o) => o.id === id) || null;
56	}
57	
58	/** Besitzer eines Objekts (Nutzer-ID) */
59	function besitzer(db, art, o) {
60	  if (!o) return null;
61	  if (art === "vorgang" || art === "flaeche") return o.nutzerId || null;
62	  if (art === "projekt") return o.anbieterId;
63	  if (art === "interesse") return o.investorId;
64	  if (art === "provision") return o.anbieterId;
65	  if (art === "nutzer") return o.id;
66	  return null;
67	}
68	
69	function bezugObjekt(db, art, id) {
70	  if (art === "nutzer") return nutzerById(db, id);
71	  return objekt(db, art, id);
72	}
73	
74	function darfBezug(db, n, art, id) {
75	  if (!BEZUG_ARTEN.includes(art)) throw ungueltig("Unbekannter Bezug");
76	  const o = bezugObjekt(db, art, id);
77	  if (!o) throw nichtGefunden();
78	  if (istAdmin(n)) return o;
79	  if (besitzer(db, art, o) !== n.id) throw verboten();
80	  return o;
81	}
82	
83	function protokoll(db, n, aktion, objektArt, objektId, text, ip = "") {
84	  db.aktivitaeten.push({ id: neueId("A"), am: jetzt(), nutzerId: n?.id || null, aktion, objektArt, objektId, text: v.text(text, 300), ip: ip || "" });
85	  if (db.aktivitaeten.length > 5000) db.aktivitaeten.splice(0, db.aktivitaeten.length - 5000);
86	}
87	
88	function nachricht(db, { bezugArt, bezugId, vonId, vonAdmin = false, system = false, text }) {
89	  const m = {
90	    id: neueId("M"),
91	    bezugArt,
92	    bezugId,
93	    vonId: vonId || null,
94	    vonAdmin,
95	    system,
96	    text: v.mehrzeilig(text, 5000),
97	    am: jetzt(),
98	    gelesenNutzer: !vonAdmin && !system ? true : false,
99	    gelesenAdmin: vonAdmin,
100	  };
101	  db.nachrichten.push(m);
102	  return m;
103	}
104	
105	function verlaufEintrag(status, n, rolle, kommentar = "") {
106	  return { status, am: jetzt(), vonId: n?.id || null, vonRolle: rolle, kommentar: v.mehrzeilig(kommentar, 1000) };
107	}
108	
109	function linkZuDemo(db, art, email, link) {
110	  db.demoLinks.unshift({ am: jetzt(), art, email, link });
111	  db.demoLinks = db.demoLinks.slice(0, 50);
112	  console.info(`[plattform-demo] ${art === "reset" ? "Passwort-Link" : "Bestätigungs-Link"} für ${email}: ${link}`);
113	}
114	
115	function tokenAnlegen(db, art, nutzerId, stunden) {
116	  const token = zufallsToken();
117	  db.tokens = db.tokens.filter((t) => !(t.nutzerId === nutzerId && t.art === art && !t.benutzt));
118	  db.tokens.push({ hash: sha256(token), art, nutzerId, ablauf: new Date(Date.now() + stunden * 3600e3).toISOString(), benutzt: false });
119	  return token;
120	}
121	
122	function tokenEinloesen(db, art, token) {
123	  const h = sha256(String(token || ""));
124	  const t = db.tokens.find((x) => x.hash === h && x.art === art);
125	  if (!t || t.benutzt || new Date(t.ablauf) < new Date()) throw ungueltig("Der Link ist ungültig oder abgelaufen. Bitte fordern Sie einen neuen an.");
126	  t.benutzt = true;
127	  const u = nutzerById(db, t.nutzerId);
128	  if (!u || !u.aktiv) throw ungueltig("Der Link ist ungültig oder abgelaufen.");
129	  return u;
130	}
131	
132	/** Offene Anfragen mit gleicher (bestätigter) E-Mail dem Konto zuordnen */
133	function verknuepfen(db, u) {
134	  if (!u?.emailBestaetigt) return 0;
135	  let anzahl = 0;
136	  for (const vg of db.vorgaenge) {
137	    if (vg.nutzerId || vg.email !== u.email) continue;
138	    vg.nutzerId = u.id;
139	    anzahl++;
140	    const rolle = ROLLE_FUER_TYP[vg.typ];
141	    if (rolle && vg.typ !== "kontakt" && !u.rollen.includes(rolle)) u.rollen.push(rolle);
142	    if (vg.flaecheId) {
143	      const f = objekt(db, "flaeche", vg.flaecheId);
144	      if (f && !f.nutzerId) f.nutzerId = u.id;
145	    }
146	  }
147	  return anzahl;
148	}
149	
150	/** Freie Zusatzdaten einer Anfrage bereinigen (flach, begrenzt) */
151	function datenBereinigen(d, tiefe = 0) {
152	  if (!d || typeof d !== "object" || Array.isArray(d)) return {};
153	  const out = {};
154	  for (const [k, wert] of Object.entries(d).slice(0, 60)) {
155	    const key = String(k).replace(/[^\w.-]/g, "").slice(0, 60);
156	    if (!key || key === "__proto__" || key === "constructor" || key === "prototype") continue;
157	    if (typeof wert === "string") out[key] = v.mehrzeilig(wert, 2000);
158	    else if (typeof wert === "number" && Number.isFinite(wert)) out[key] = wert;
159	    else if (typeof wert === "boolean") out[key] = wert;
160	    else if (Array.isArray(wert)) out[key] = wert.slice(0, 30).map((x) => (typeof x === "number" || typeof x === "boolean" ? x : v.text(x, 200)));
161	    else if (wert && typeof wert === "object" && tiefe < 1) out[key] = datenBereinigen(wert, tiefe + 1);
162	  }
163	  return out;
164	}
165	
166	const nachDatum = (feld = "geaendertAm") => (a, b) => String(b[feld] || "").localeCompare(String(a[feld] || ""));
167	
168	// ================================================================ Konto
169	
170	export async function anmelden({ email, passwort }) {
171	  const e = v.email(email);
172	  const db = await lesen();
173	  const u = db.nutzer.find((x) => x.email === e);
174	  const ok = await passwortPruefen(String(passwort || ""), u?.passwortHash);
175	  if (!u || !ok || !u.aktiv) return null;
176	  return aendern((db2) => {
177	    const x = nutzerById(db2, u.id);
178	    x.letzterLogin = jetzt();
179	    verknuepfen(db2, x);
180	    protokoll(db2, x, "login", "nutzer", x.id, "Anmeldung");
181	    return ohneGeheimnis(x);
182	  });
183	}
184	
185	export async function nutzerFuerSitzung(id) {
186	  const db = await lesen();
187	  const u = nutzerById(db, id);
188	  return u && u.aktiv ? ohneGeheimnis(u) : null;
189	}
190	
191	export async function registrieren({ email, passwort, vorname, nachname, firma, telefon, rollen, vorgangId, basisUrl, ip }) {
192	  const e = v.email(email);
193	  v.pflicht(e, "Bitte geben Sie eine gültige E-Mail-Adresse an.");
194	  const pwFehler = v.passwortFehler(passwort);
195	  v.pflicht(!pwFehler, pwFehler);
196	  const vn = v.text(vorname, 80);
197	  const nn = v.text(nachname, 80);
198	  v.pflicht(vn && nn, "Bitte geben Sie Vor- und Nachnamen an.");
199	  const r = v.mehrfach(rollen, ROLLEN_IDS);
200	  v.pflicht(r.length > 0, "Bitte wählen Sie mindestens eine Rolle.");
201	  const hash = await passwortHash(passwort);
202	
203	  return aendern((db) => {
204	    if (db.nutzer.some((u) => u.email === e)) {
205	      throw konflikt("Für diese E-Mail-Adresse besteht bereits ein Konto. Bitte melden Sie sich an oder setzen Sie Ihr Passwort zurück.");
206	    }
207	    const u = {
208	      id: neueId("U"),
209	      email: e,
210	      vorname: vn,
211	      nachname: nn,
212	      firma: v.text(firma, 120),
213	      telefon: v.text(telefon, 40),
214	      rollen: r,
215	      passwortHash: hash,
216	      sitzungVersion: 0,
217	      aktiv: true,
218	      emailBestaetigt: false,
219	      erstelltAm: jetzt(),
220	      letzterLogin: jetzt(),
221	      suchprofil: null,
222	    };
223	    db.nutzer.push(u);
224	
225	    // Anfrage aus demselben Ablauf sofort zuordnen (Kennung + E-Mail müssen passen)
226	    let verknuepft = null;
227	    const vid = v.kennung(vorgangId);
228	    if (vid) {
229	      const vg = objekt(db, "vorgang", vid);
230	      if (vg && !vg.nutzerId && vg.email === e) {
231	        vg.nutzerId = u.id;
232	        verknuepft = vg.id;
233	        if (vg.flaecheId) {
234	          const f = objekt(db, "flaeche", vg.flaecheId);
235	          if (f && !f.nutzerId) f.nutzerId = u.id;
236	        }
237	      }
238	    }
239	    const token = tokenAnlegen(db, "email", u.id, 72);
240	    linkZuDemo(db, "email", e, `${basisUrl}/api/auth/email-bestaetigen?token=${token}`);
241	    protokoll(db, u, "registrierung", "nutzer", u.id, `Registrierung als ${r.join(", ")}`, ip);
242	    nachricht(db, {
243	      bezugArt: "nutzer",
244	      bezugId: u.id,
245	      vonAdmin: true,
246	      system: true,
247	      text: "Willkommen im Portal von ÖkoInvest. Bitte bestätigen Sie Ihre E-Mail-Adresse über den Link, den wir Ihnen gesendet haben – danach ordnen wir frühere Anfragen mit dieser Adresse automatisch Ihrem Konto zu.",
248	    });
249	    return { nutzer: ohneGeheimnis(u), vorgangVerknuepft: verknuepft };
250	  });
251	}
252	
253	export async function emailBestaetigen({ token }) {
254	  return aendern((db) => {
255	    const u = tokenEinloesen(db, "email", token);
256	    u.emailBestaetigt = true;
257	    const anzahl = verknuepfen(db, u);
258	    protokoll(db, u, "email", "nutzer", u.id, `E-Mail bestätigt, ${anzahl} Anfrage(n) zugeordnet`);
259	    return ohneGeheimnis(u);
260	  });
261	}
262	
263	export async function passwortVergessen({ email, basisUrl, ip }) {
264	  const e = v.email(email);
265	  if (!e) return { ok: true };
266	  await aendern((db) => {
267	    const u = db.nutzer.find((x) => x.email === e && x.aktiv);
268	    if (!u) return;
269	    const token = tokenAnlegen(db, "reset", u.id, 1);
270	    linkZuDemo(db, "reset", e, `${basisUrl}/passwort-vergessen?token=${token}`);
271	    protokoll(db, u, "passwort_vergessen", "nutzer", u.id, "Passwort-Link angefordert", ip);
272	  });
273	  return { ok: true };
274	}
275	
276	export async function passwortSetzen({ token, passwort, ip }) {
277	  const pwFehler = v.passwortFehler(passwort);
278	  v.pflicht(!pwFehler, pwFehler);
279	  const hash = await passwortHash(passwort);
280	  return aendern((db) => {
281	    const u = tokenEinloesen(db, "reset", token);
282	    u.passwortHash = hash;
283	    u.sitzungVersion = (u.sitzungVersion || 0) + 1;
284	    u.emailBestaetigt = true; // Besitz der Adresse nachgewiesen
285	    verknuepfen(db, u);
286	    protokoll(db, u, "passwort_gesetzt", "nutzer", u.id, "Passwort neu gesetzt", ip);
287	    return ohneGeheimnis(u);
288	  });
289	}
290	
291	export async function passwortAendern(n, { alt, neu }) {
292	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
293	  const pwFehler = v.passwortFehler(neu);
294	  v.pflicht(!pwFehler, pwFehler);
295	  const db0 = await lesen();
296	  const u0 = nutzerById(db0, n.id);
297	  if (!(await passwortPruefen(String(alt || ""), u0?.passwortHash))) throw ungueltig("Das bisherige Passwort stimmt nicht.");
298	  const hash = await passwortHash(neu);
299	  return aendern((db) => {
300	    const u = nutzerById(db, n.id);
301	    u.passwortHash = hash;
302	    u.sitzungVersion = (u.sitzungVersion || 0) + 1;
303	    protokoll(db, u, "passwort_geaendert", "nutzer", u.id, "Passwort geändert");
304	    return ohneGeheimnis(u);
305	  });
306	}
307	
308	export async function profilSpeichern(n, daten) {
309	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
310	  return aendern((db) => {
311	    const u = nutzerById(db, n.id);
312	    const vn = v.text(daten.vorname, 80);
313	    const nn = v.text(daten.nachname, 80);
314	    v.pflicht(vn && nn, "Bitte geben Sie Vor- und Nachnamen an.");
315	    u.vorname = vn;
316	    u.nachname = nn;
317	    u.firma = v.text(daten.firma, 120);
318	    u.telefon = v.text(daten.telefon, 40);
319	    if (Array.isArray(daten.rollen)) {
320	      const r = v.mehrfach(daten.rollen, ROLLEN_IDS);
321	      v.pflicht(r.length > 0, "Bitte wählen Sie mindestens eine Rolle.");
322	      u.rollen = [...r, ...(u.rollen.includes("admin") ? ["admin"] : [])];
323	    }
324	    protokoll(db, u, "profil", "nutzer", u.id, "Profil aktualisiert");
325	    return ohneGeheimnis(u);
326	  });
327	}
328	
329	export async function suchprofilSpeichern(n, p) {
330	  rolleNoetig(n, ["investor"], "Suchprofile sind für Investoren.");
331	  const profil = {
332	    mwpMin: v.zahl(p?.mwpMin, { min: 0, max: 5000 }),
333	    mwpMax: v.zahl(p?.mwpMax, { min: 0, max: 5000 }),
334	    phasen: v.mehrfach(p?.phasen, PHASEN.map((x) => x.id)),
335	    laender: v.mehrfach(p?.laender, LAENDER),
336	    typen: v.mehrfach(p?.typen, PROJEKT_TYPEN),
337	    ticketMin: v.zahl(p?.ticketMin, { min: 0, max: 1e10 }),
338	    ticketMax: v.zahl(p?.ticketMax, { min: 0, max: 1e10 }),
339	    benachrichtigen: v.wahr(p?.benachrichtigen),
340	  };
341	  if (profil.mwpMin !== null && profil.mwpMax !== null) v.pflicht(profil.mwpMin <= profil.mwpMax, "MWp: Minimum größer als Maximum.");
342	  if (profil.ticketMin !== null && profil.ticketMax !== null) v.pflicht(profil.ticketMin <= profil.ticketMax, "Ticket: Minimum größer als Maximum.");
343	  return aendern((db) => {
344	    const u = nutzerById(db, n.id);
345	    u.suchprofil = profil;
346	    protokoll(db, u, "suchprofil", "nutzer", u.id, "Suchprofil gespeichert");
347	    return profil;
348	  });
349	}
