351	// ================================================================ Anfrage (öffentlich)
352	
353	export async function anfrageAnlegen({ typ, kontakt, daten, herkunft, ip, einwilligungText, nutzer }) {
354	  const t = v.auswahl(typ, VORGANG_TYPEN);
355	  v.pflicht(t, "Unbekannter Anfragetyp.");
356	  const k = {
357	    anrede: v.text(kontakt?.anrede, 20),
358	    vorname: v.text(kontakt?.vorname, 80),
359	    nachname: v.text(kontakt?.nachname, 80),
360	    firma: v.text(kontakt?.firma, 120),
361	    email: v.email(kontakt?.email),
362	    telefon: v.text(kontakt?.telefon, 40),
363	    plz: v.plz(kontakt?.plz),
364	    ort: v.text(kontakt?.ort, 80),
365	    land: v.auswahl(kontakt?.land, LAENDER, ""),
366	  };
367	  v.pflicht(k.vorname && k.nachname, "Bitte geben Sie Vor- und Nachnamen an.");
368	  v.pflicht(k.email, "Bitte geben Sie eine gültige E-Mail-Adresse an.");
369	  const d = datenBereinigen(daten);
370	  v.pflicht(JSON.stringify(d).length <= 20000, "Zu viele Zusatzdaten.");
371	  const h = datenBereinigen(herkunft);
372	
373	  return aendern((db) => {
374	    const u = nutzer && nutzer.email === k.email && nutzer.emailBestaetigt ? nutzerById(db, nutzer.id) : null;
375	    const vg = {
376	      id: neueId("V"),
377	      typ: t,
378	      status: PROZESSE.vorgang.start,
379	      statusVerlauf: [verlaufEintrag(PROZESSE.vorgang.start, u, "eigentuemer", "")],
380	      nutzerId: u?.id || null,
381	      email: k.email,
382	      kontakt: k,
383	      daten: d,
384	      herkunft: h,
385	      ip: ip || "",
386	      einwilligung: { am: jetzt(), ip: ip || "", text: v.text(einwilligungText, 400) },
387	      zustaendigId: null,
388	      flaecheId: null,
389	      erstelltAm: jetzt(),
390	      geaendertAm: jetzt(),
391	    };
392	    if (t === "flaeche" || t === "agri") {
393	      const haWert = v.zahl(d.ha ?? d.hektar ?? d.flaeche ?? d.flaecheHa, { min: 0, max: 100000, stellen: 2 });
394	      const f = {
395	        id: neueId("F"),
396	        nutzerId: u?.id || null,
397	        vorgangId: vg.id,
398	        bezeichnung: v.text(d.bezeichnung, 120) || `Fläche ${[k.plz, k.ort].filter(Boolean).join(" ") || "aus Anfrage"}`,
399	        land: k.land || "DE",
400	        bundesland: v.auswahl(d.bundesland, BUNDESLAENDER[k.land || "DE"] || [], ""),
401	        plz: k.plz,
402	        ort: k.ort,
403	        gemarkung: "",
404	        flurstuecke: [],
405	        ha: haWert,
406	        nutzung: v.auswahl(d.nutzung, FLAECHE_NUTZUNG, "acker"),
407	        agri: t === "agri",
408	        eigentum: "eigentum",
409	        hinweise: v.mehrzeilig(d.nachricht, 2000),
410	        status: "entwurf",
411	        statusVerlauf: [verlaufEintrag("entwurf", u, "system", "Aus Anfrage angelegt")],
412	        pachtangebot: null,
413	        ablehnGrund: "",
414	        zustaendigId: null,
415	        erstelltAm: jetzt(),
416	        geaendertAm: jetzt(),
417	      };
418	      db.flaechen.push(f);
419	      vg.flaecheId = f.id;
420	    }
421	    db.vorgaenge.push(vg);
422	    protokoll(db, u, "anfrage", "vorgang", vg.id, `Anfrage ${VORGANG_TYPEN[t]} von ${k.email}`, ip);
423	    return { id: vg.id, vorgang: { id: vg.id, typ: vg.typ, status: vg.status, flaecheId: vg.flaecheId } };
424	  });
425	}
