427	// ================================================================ Vorgänge
428	
429	function vorgangListenEintrag(db, vg, admin) {
430	  const z = nutzerById(db, vg.zustaendigId);
431	  const letzte = vg.statusVerlauf[vg.statusVerlauf.length - 1];
432	  return {
433	    id: vg.id,
434	    typ: vg.typ,
435	    status: vg.status,
436	    erstelltAm: vg.erstelltAm,
