768	  const zugriff = admin ? "admin" : eigentuemer ? "eigentuemer" : ndaFrei ? "nda" : "oeffentlich";
769	  const out = { projekt: boerseEintrag(db, p, n), zugriff, interesse, vertraulich: null, dokumente: [] };
