                    <Link role="menuitem" href="/" className="flex items-center gap-2.5 rounded-xl px-3 py-2 text-[14px] text-ink-700 hover:bg-ink-50">
                      <Building2 aria-hidden="true" className="h-4 w-4" /> Zur Website
