      kinder.push(
        neu(`<< /Type /Page /Parent ${seitenbaum} 0 R /MediaBox [0 0 ${zahl(this.breite)} ${zahl(this.hoehe)}] /Resources << /Font << /F1 ${f1} 0 R /F2 ${f2} 0 R >> >> /Contents ${strom} 0 R >>`)
      );
    }
    objekte[katalog - 1] = `<< /Type /Catalog /Pages ${seitenbaum} 0 R >>`;
