w('app/api/admin/aufgaben/route.js','''// GET  /api/admin/aufgaben?ansicht=meine|alle|ueberfaellig|erledigt&bezug=art:id – Aufgaben & Wiedervorlagen (nur admin)
// POST /api/admin/aufgaben – { titel, beschreibung?, faelligAm: "JJJJ-MM-TT", zustaendigId?, bezugArt?, bezugId? }
import { route } from "@/lib/plattform/server/route";

export const GET = route({ admin: true }, async ({ backend, nutzer, suche }) => {
  const ansicht = suche.get("ansicht") || "alle";
  const [bezugArt, bezugId] = (suche.get("bezug") || "").split(":");
