      <div className="mt-4 border-t border-ink-100 pt-4">
        <AufgabeFormular konten={konten} nutzerId={nutzer.id} bezugArt={bezugArt} bezugId={bezugId} kompakt />
      </div>
    </Karte>
  );
}

