// node p2_shots.mjs [breite ...] – Screenshots der neuen Portalansichten (Ausbaustufe 2), eingeloggt je Rolle.
// Ausgabe: Status, Laufzeit-/Konsolenfehler, horizontaler Überlauf. Bilder: shots/p2_<name>_<breite>.png
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";

const B = "http://localhost:3100";
const breiten = process.argv.slice(2).map(Number).filter(Boolean);
const BREITEN = breiten.length ? breiten : [1440, 390];
const nur = process.env.P2_NUR ? process.env.P2_NUR.split(",") : null;

async function api(ctx, pfad) {
  const r = await ctx.request.get(B + pfad, { timeout: 300000 });
  return r.json();
}

const browser = await chromium.launch();
const probleme = [];

async function sitzung(email, breite) {
  const ctx = await browser.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 300000 });
  if (!r.ok()) throw new Error(`Login ${email}: ${r.status()}`);
  return ctx;
}

async function schuss(ctx, name, pfad, breite, { aktion } = {}) {
  if (nur && !nur.includes(name)) return;
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message.slice(0, 200)));
  p.on("console", (m) => m.type() === "error" && !/hydrat|Download the React DevTools/i.test(m.text()) && fehler.push("CONSOLE " + m.text().slice(0, 200)));
  const res = await p.goto(B + pfad, { waitUntil: "networkidle", timeout: 300000 });
  await p.waitForTimeout(700);
  if (aktion) await aktion(p);
  const w = await p.evaluate(() => document.documentElement.scrollWidth);
  const datei = `p2_${name}_${breite}.png`;
  await p.screenshot({ path: fileURLToPath(new URL("./shots/" + datei, import.meta.url)), fullPage: !aktion });
  const zeile = `${res.status()} ${pfad} → ${datei}${w > breite ? ` ÜBERLAUF ${w}` : ""}${fehler.length ? "\n   " + fehler.join("\n   ") : ""}`;
  console.log(zeile);
  if (res.status() !== 200 || w > breite || fehler.length) probleme.push(zeile);
  await p.close();
