      <circle cx="318" cy="60" r="17" fill={FARBEN.sonne} opacity="0.9" />
      <path d="M0 78 C 80 60, 160 70, 240 62 S 360 58, 400 66 L400 170 L0 170 Z" fill={FARBEN.boden} />
